"""Generate docs/controls.md (the control catalogue and runbooks) from the control headers.

The SQL files are the single source of truth; CI fails if this document is stale.
"""

from __future__ import annotations

from pathlib import Path

from hdq.controls import load_controls
from hdq.issues import SLA_DAYS


def render() -> str:
    controls = load_controls()
    out = [
        "# Control catalogue and triage runbooks",
        "",
        "Generated by `hdq docs` from the headers in `controls/*.sql`. Do not edit by hand.",
        "",
        "| Control | Dimension | Severity | SLA (business days) | Owner |",
        "|---|---|---|---|---|",
    ]
    for c in controls:
        out.append(
            f"| [{c.id}](#{c.id.lower()}) {c.name} | {c.dimension} | {c.severity} "
            f"| {SLA_DAYS[c.severity]} | {c.owner} |"
        )
    for c in controls:
        out += [
            "",
            f"## {c.id}",
            "",
            f"**{c.name}.** {c.dimension.capitalize()}, {c.severity} severity, owned by {c.owner}. "
            f"Source: [`controls/{c.path.name}`](../controls/{c.path.name}).",
            "",
            f"*What it checks.* {c.description}",
            "",
            f"*Why it matters.* {c.impact}",
            "",
            "*Triage runbook.*",
            "",
        ]
        out += [f"{i}. {step}" for i, step in enumerate(c.runbook, 1)]
    return "\n".join(out) + "\n"


def write(path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render())
    return path
